//! `forge_provider::extract` with archives generated by the tests (nothing binary is
//! committed): zip-slip and Windows name hazards, links, decompression bombs, strip_root,
//! the atomic move, case sensitivity of staging, progress and cancellation. The `*_online`
//! tests (ignored by default) extract real upstream archives; see `tests/verify.rs` for the
//! download cache (`FORGEBOX_TEST_CACHE`).

mod support;

use std::cell::Cell;
use std::fs::{self, File};
use std::io::{Cursor, Write};
use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime};

use forge_core::event::EventBus;
use forge_core::jobs::{JobRegistry, JobSpec, JobState};
use forge_core::platform::{self, CaseSensitivitySupport};
use forge_provider::extract::{
    ArchiveFormat, ExtractLimits, ExtractReport, ExtractRequest, Extractor, StripRoot, extract,
};
use sevenz_rust2::{ArchiveEntry, ArchiveWriter};
use zip::write::SimpleFileOptions;
use zip::{CompressionMethod, DateTime, System, ZipWriter};

// ---------------------------------------------------------------- helpers

struct Env {
    dir: tempfile::TempDir,
}

impl Env {
    fn new() -> Self {
        Self {
            dir: tempfile::tempdir().unwrap(),
        }
    }

    fn path(&self, rel: &str) -> PathBuf {
        self.dir.path().join(rel)
    }

    fn stage(&self) -> PathBuf {
        self.path("tmp/stage")
    }

    fn dest(&self) -> PathBuf {
        self.path("bin/tool/1.0.0")
    }

    fn archive(&self, name: &str) -> PathBuf {
        let dir = self.path("downloads");
        fs::create_dir_all(&dir).unwrap();
        dir.join(name)
    }

    fn request(&self, archive: &Path, format: ArchiveFormat) -> ExtractRequest {
        ExtractRequest::new(archive, format, self.dest(), self.stage())
    }

    /// After a rejected archive: no destination, nothing left in staging, and no file named
    /// `evil.txt` anywhere under the test root.
    fn assert_untouched(&self) {
        assert!(!self.dest().exists(), "destination must not exist");
        if self.stage().exists() {
            let left: Vec<_> = fs::read_dir(self.stage()).unwrap().collect();
            assert!(left.is_empty(), "staging not cleaned: {left:?}");
        }
        let mut pending = vec![self.dir.path().to_path_buf()];
        while let Some(dir) = pending.pop() {
            for entry in fs::read_dir(&dir).unwrap() {
                let entry = entry.unwrap();
                assert_ne!(entry.file_name(), "evil.txt", "{:?}", entry.path());
                if entry.file_type().unwrap().is_dir() {
                    pending.push(entry.path());
                }
            }
        }
    }
}

fn files_under(root: &Path) -> Vec<String> {
    let mut out = Vec::new();
    let mut pending = vec![root.to_path_buf()];
    while let Some(dir) = pending.pop() {
        for entry in fs::read_dir(&dir).unwrap() {
            let entry = entry.unwrap();
            let rel = entry
                .path()
                .strip_prefix(root)
                .unwrap()
                .to_string_lossy()
                .replace('\\', "/");
            if entry.file_type().unwrap().is_dir() {
                out.push(format!("{rel}/"));
                pending.push(entry.path());
            } else {
                out.push(rel);
            }
        }
    }
    out.sort();
    out
}

async fn rejected(req: ExtractRequest) -> forge_core::ForgeError {
    let err = extract(req).await.unwrap_err();
    assert_eq!(err.code(), "verification_failed", "{err}");
    err
}

fn dos_time() -> DateTime {
    DateTime::from_date_and_time(2024, 5, 17, 10, 20, 30).unwrap()
}

fn options() -> SimpleFileOptions {
    SimpleFileOptions::default()
        .compression_method(CompressionMethod::Deflated)
        .last_modified_time(dos_time())
}

enum Z<'a> {
    File(&'a str, &'a [u8]),
    Dir(&'a str),
    Symlink(&'a str, &'a str),
    Attrs(&'a str, System, u32),
}

fn zip_archive(path: &Path, items: &[Z<'_>]) {
    let mut w = ZipWriter::new(File::create(path).unwrap());
    for item in items {
        match item {
            Z::File(name, data) => {
                w.start_file(*name, options()).unwrap();
                w.write_all(data).unwrap();
            }
            Z::Dir(name) => w.add_directory(*name, options()).unwrap(),
            Z::Symlink(name, target) => w.add_symlink(*name, *target, options()).unwrap(),
            Z::Attrs(name, system, attrs) => {
                w.start_file(*name, options().system(*system).external_attributes(*attrs))
                    .unwrap();
                w.write_all(b"data").unwrap();
            }
        }
    }
    w.finish().unwrap();
}

enum T<'a> {
    File(&'a str, &'a [u8]),
    Dir(&'a str),
    Symlink(&'a str, &'a str),
    HardLink(&'a str, &'a str),
    Fifo(&'a str),
}

/// Raw tar header: the name is copied byte for byte (the `tar` builder would refuse `..`).
fn tar_header(name: &str, kind: tar::EntryType, size: u64, link: Option<&str>) -> tar::Header {
    let mut header = tar::Header::new_gnu();
    let bytes = name.as_bytes();
    header.as_old_mut().name[..bytes.len()].copy_from_slice(bytes);
    header.set_entry_type(kind);
    header.set_size(size);
    header.set_mode(0o644);
    header.set_mtime(1_700_000_000);
    if let Some(link) = link {
        header.set_link_name_literal(link).unwrap();
    }
    header.set_cksum();
    header
}

fn tar_bytes(items: &[T<'_>]) -> Vec<u8> {
    let mut builder = tar::Builder::new(Vec::new());
    for item in items {
        let (header, data): (tar::Header, &[u8]) = match item {
            T::File(name, data) => (
                tar_header(name, tar::EntryType::Regular, data.len() as u64, None),
                data,
            ),
            T::Dir(name) => (tar_header(name, tar::EntryType::Directory, 0, None), &[]),
            T::Symlink(name, target) => (
                tar_header(name, tar::EntryType::Symlink, 0, Some(target)),
                &[],
            ),
            T::HardLink(name, target) => {
                (tar_header(name, tar::EntryType::Link, 0, Some(target)), &[])
            }
            T::Fifo(name) => (tar_header(name, tar::EntryType::Fifo, 0, None), &[]),
        };
        builder.append(&header, data).unwrap();
    }
    builder.into_inner().unwrap()
}

fn tar_gz(path: &Path, items: &[T<'_>]) {
    let mut gz =
        flate2::write::GzEncoder::new(File::create(path).unwrap(), flate2::Compression::fast());
    gz.write_all(&tar_bytes(items)).unwrap();
    gz.finish().unwrap();
}

fn tar_xz(path: &Path, items: &[T<'_>]) {
    let mut xz = lzma_rust2::XzWriter::new(
        File::create(path).unwrap(),
        lzma_rust2::XzOptions::with_preset(1),
    )
    .unwrap();
    xz.write_all(&tar_bytes(items)).unwrap();
    xz.finish().unwrap();
}

fn seven_z(path: &Path, entries: Vec<(ArchiveEntry, Option<&[u8]>)>) {
    let mut w = ArchiveWriter::create(path).unwrap();
    for (entry, data) in entries {
        w.push_archive_entry(entry, data.map(Cursor::new)).unwrap();
    }
    w.finish().unwrap();
}

// ---------------------------------------------------------------- zip: malicious

#[tokio::test]
async fn zip_with_parent_traversal_is_rejected() {
    let env = Env::new();
    for name in ["../evil.txt", "ok/../../evil.txt", "..\\evil.txt"] {
        let archive = env.archive("slip.zip");
        zip_archive(
            &archive,
            &[Z::File("good.txt", b"fine"), Z::File(name, b"pwned")],
        );
        let err = rejected(env.request(&archive, ArchiveFormat::Zip)).await;
        assert!(err.to_string().contains("unsafe archive entry"), "{err}");
        env.assert_untouched();
    }
}

