#[tokio::test]
async fn zip_with_reparse_point_or_device_mode_is_rejected() {
    let env = Env::new();
    let cases = [
        // FILE_ATTRIBUTE_REPARSE_POINT from a Windows zipper.
        Z::Attrs("junction", System::Dos, 0x400 | 0x10),
        // Unix character device and fifo.
        Z::Attrs("dev", System::Unix, 0o020_644 << 16),
        Z::Attrs("fifo", System::Unix, 0o010_644 << 16),
    ];
    for case in cases {
        let archive = env.archive("attrs.zip");
        zip_archive(&archive, &[case]);
        rejected(env.request(&archive, ArchiveFormat::Zip)).await;
        env.assert_untouched();
    }
}

