#[tokio::test]
async fn seven_z_with_links_is_rejected() {
    let env = Env::new();
    // Unix symlink stored by p7zip (mode in the high bits, FILE_ATTRIBUTE_UNIX_EXTENSION).
    let mut unix_link = ArchiveEntry::new_file("app/link");
    unix_link.has_windows_attributes = true;
    unix_link.windows_attributes = 0x8000 | (0o120_777 << 16);
    // Windows reparse point (junction/symlink) attribute.
    let mut reparse = ArchiveEntry::new_directory("app/junction");
    reparse.has_windows_attributes = true;
    reparse.windows_attributes = 0x400 | 0x10;
    for (name, entry, data) in [
        ("unix.7z", unix_link, Some(b"/etc".as_slice())),
        ("reparse.7z", reparse, None),
    ] {
        let archive = env.archive(name);
        seven_z(&archive, vec![(entry, data)]);
        rejected(env.request(&archive, ArchiveFormat::SevenZ)).await;
        env.assert_untouched();
    }
}

#[tokio::test]
async fn seven_z_extracts_with_strip() {
    let env = Env::new();
    let archive = env.archive("tool.7z");
    // Entries with data only: sevenz-rust2 0.20 writes the anti-item bitset inverted, so
    // the directories and empty files it writes read back as anti-items (see
    // `seven_z_anti_items_are_skipped`). Real directories are covered by the online test
    // with Node's 7z.
    seven_z(
        &archive,
        vec![
            (
                ArchiveEntry::new_file("tool-2.0/bin/tool.exe"),
                Some(b"MZ seven".as_slice()),
            ),
            (
                ArchiveEntry::new_file("tool-2.0/README"),
                Some(b"read me".as_slice()),
            ),
        ],
    );
    let report = extract(env.request(&archive, ArchiveFormat::SevenZ))
        .await
        .unwrap();
    assert_eq!(report.stripped_root.as_deref(), Some("tool-2.0"));
    assert_eq!(
        files_under(&env.dest()),
        vec!["README", "bin/", "bin/tool.exe"]
    );
    assert_eq!(
        fs::read(env.dest().join("bin/tool.exe")).unwrap(),
        b"MZ seven"
    );
}

#[tokio::test]
async fn seven_z_anti_items_are_skipped() {
    let env = Env::new();
    let archive = env.archive("anti.7z");
    seven_z(
        &archive,
        vec![
            (
                ArchiveEntry::new_file("pkg/kept.txt"),
                Some(b"kept".as_slice()),
            ),
            (ArchiveEntry::new_file("pkg/empty-marker"), None),
        ],
    );
    let reader =
        sevenz_rust2::ArchiveReader::open(&archive, sevenz_rust2::Password::empty()).unwrap();
    let marker = reader
        .archive()
        .files
        .iter()
        .find(|f| f.name() == "pkg/empty-marker")
        .unwrap();
    assert!(
        marker.is_anti_item(),
        "fixture relies on the writer behaviour"
    );
    drop(reader);
    extract(env.request(&archive, ArchiveFormat::SevenZ))
        .await
        .unwrap();
    assert_eq!(files_under(&env.dest()), vec!["kept.txt"]);
}

// ---------------------------------------------------------------- staging, jobs

impl Env {
    fn assert_untouched_staging(&self) {
        if self.stage().exists() {
            let left: Vec<_> = fs::read_dir(self.stage()).unwrap().collect();
            assert!(left.is_empty(), "staging not cleaned: {left:?}");
        }
    }
}

#[tokio::test]
async fn staging_takes_the_case_sensitivity_of_the_destination() {
    let env = Env::new();
    let cs = platform::current();
    let cs = cs.case_sensitive_fs();
    let tmp = env.path("tmp");
    fs::create_dir_all(&tmp).unwrap();
    if !matches!(cs.support(&tmp), CaseSensitivitySupport::Supported) {
        eprintln!("SKIPPED: per-directory case sensitivity unsupported here");
        return;
    }
    // tmp/ is case-sensitive (as created by ForgeRoot::init); tmp/stage inherits it.
    cs.set(&tmp, true).unwrap();
    let www = env.path("www");
    fs::create_dir_all(&www).unwrap();
    cs.set(&www, true).unwrap();

    let archive = env.archive("site.zip");
    zip_archive(&archive, &[Z::File("index.php", b"<?php")]);

    // bin/ is insensitive: the installed version must be too.
    let report = extract(env.request(&archive, ArchiveFormat::Zip))
        .await
        .unwrap();
    assert!(
        !cs.get(&report.dest).unwrap(),
        "bin/<tool>/<version> stays insensitive"
    );

    // www/ is sensitive: extracting a site there keeps the flag.
    let site = www.join("site");
    extract(ExtractRequest::new(
        &archive,
        ArchiveFormat::Zip,
        &site,
        env.stage(),
    ))
    .await
    .unwrap();
    assert!(cs.get(&site).unwrap());
}

#[tokio::test]
async fn progress_is_reported_per_entry_in_a_job() {
    let env = Env::new();
    let archive = env.archive("many.zip");
    let names: Vec<String> = (0..300).map(|i| format!("pkg/f{i:03}.txt")).collect();
    let data = support::payload(16 * 1024);
    let items: Vec<Z<'_>> = names.iter().map(|n| Z::File(n, &data)).collect();
    zip_archive(&archive, &items);

    let bus = EventBus::new();
    let jobs = JobRegistry::new(bus.clone());
    let mut events = bus.subscribe();
    let extractor = Extractor::new(&platform::current());
    let req = env.request(&archive, ArchiveFormat::Zip);
    let handle = jobs.spawn(JobSpec::new("extract"), move |ctx| async move {
        extractor.extract_in_job(&ctx, req).await
    });
    let info = handle.wait(Duration::from_secs(60)).await.unwrap();
    assert_eq!(info.state, JobState::Done, "{info:?}");
    let report: ExtractReport = serde_json::from_value(info.result.unwrap()).unwrap();
    assert_eq!(report.files, 300);

    let mut messages = Vec::new();
    while let Ok(Some(event)) =
        tokio::time::timeout(Duration::from_millis(200), events.recv()).await
    {
        if event.kind == forge_core::event::EventKind::JobProgress {
            if let Some(m) = event.payload.get("message") {
                messages.push(m.as_str().unwrap_or_default().to_owned());
            }
        }
    }
    assert!(
        messages.iter().any(|m| m.starts_with("Extraindo")),
        "{messages:?}"
    );
    assert_eq!(info.progress.pct, Some(100.0));
}

#[tokio::test]
async fn cancellation_stops_and_cleans_up() {
    let env = Env::new();
    let archive = env.archive("cancel.zip");
    let names: Vec<String> = (0..50).map(|i| format!("pkg/f{i}.txt")).collect();
    let items: Vec<Z<'_>> = names.iter().map(|n| Z::File(n, b"x")).collect();
    zip_archive(&archive, &items);

    // Deterministic: cancellation becomes visible at the 20th poll.
    let polls = Cell::new(0u32);
    let cancelled = || {
        polls.set(polls.get() + 1);
        polls.get() > 20
    };
    let extractor = Extractor::new(&platform::current());
    let err = extractor
        .extract_blocking(
            &env.request(&archive, ArchiveFormat::Zip),
            &mut |_| {},
            &cancelled,
        )
        .unwrap_err();
    assert_eq!(err.code(), "cancelled");
    env.assert_untouched();
}

// ---------------------------------------------------------------- online

fn cache_dir() -> PathBuf {
    let dir = std::env::var_os("FORGEBOX_TEST_CACHE")
        .map(PathBuf::from)
        .unwrap_or_else(|| std::env::temp_dir().join("forgebox-test-cache"));
    fs::create_dir_all(&dir).unwrap();
    dir
}

/// `cache/<name>` with the given sha256, downloaded through the download engine if needed.
async fn cached(url: &str, name: &str, sha256: &str) -> PathBuf {
    let dest = cache_dir().join(name);
    if dest.is_file() {
        let report = forge_provider::verify::verify_file(
            &dest,
            forge_provider::verify::Expect::sha256(sha256),
        )
        .await;
        if report.is_ok() {
            return dest;
        }
    }
    let harness = support::Harness::new(|c| {
        c.proxy = forge_provider::download::ProxySetting::System;
    });
    let mut events = harness.events();
    let job = harness
        .manager
        .download(
            forge_provider::download::DownloadRequest::new(vec![url.parse().unwrap()], &dest)
                .expected_sha256(sha256),
        )
        .await
        .unwrap();
    harness.wait_terminal(&mut events, job).await;
    let info = harness.jobs.get(job).unwrap();
    assert_eq!(info.state, JobState::Done, "{url}: {info:?}");
    dest
}

/// sha256 of `file` in Node's SHASUMS256.txt, after checking its PGP signature with the
/// embedded `nodejs` keyring.
async fn node_sha256(version: &str, file: &str) -> String {
    let dir = cache_dir().join(format!("node-{version}"));
    fs::create_dir_all(&dir).unwrap();
    for name in ["SHASUMS256.txt", "SHASUMS256.txt.sig"] {
        if !dir.join(name).is_file() {
            let harness = support::Harness::new(|c| {
                c.proxy = forge_provider::download::ProxySetting::System;
            });
            let mut events = harness.events();
            let job = harness
                .manager
                .download(forge_provider::download::DownloadRequest::new(
                    vec![
                        format!("https://nodejs.org/dist/{version}/{name}")
                            .parse()
                            .unwrap(),
                    ],
                    dir.join(name),
                ))
                .await
                .unwrap();
            harness.wait_terminal(&mut events, job).await;
            assert_eq!(harness.jobs.get(job).unwrap().state, JobState::Done);
        }
    }
    forge_provider::verify::verify_file(
        dir.join("SHASUMS256.txt"),
        forge_provider::verify::Expect::unverified().signature(
            forge_provider::verify::Signature::Pgp {
                sig_path: dir.join("SHASUMS256.txt.sig"),
                keyring: forge_provider::verify::PgpKeyring::embedded("nodejs"),
            },
        ),
    )
    .await
    .unwrap();
    let text = fs::read_to_string(dir.join("SHASUMS256.txt")).unwrap();
    text.lines()
        .find_map(|l| {
            let (sha, name) = l.split_once("  ")?;
            (name == file).then(|| sha.to_owned())
        })
        .unwrap_or_else(|| panic!("{file} not in SHASUMS256.txt"))
}

async fn node_archive(file: &str) -> PathBuf {
    let version = "v24.22.1";
    let sha = node_sha256(version, file).await;
    cached(
        &format!("https://nodejs.org/dist/{version}/{file}"),
        &format!("node-{version}/{file}"),
        &sha,
    )
    .await
}

#[tokio::test]
#[ignore = "downloads from nginx.org and windows.php.net"]
async fn real_zip_archives_online() {
    let env = Env::new();

    let nginx = cached(
        "https://nginx.org/download/nginx-1.28.3.zip",
        "nginx-1.28.3.zip",
        "aad7bf75d669ece7671688bfdf35f1093d6a30d2e62469405f4d55d8d82d5fd3",
    )
    .await;
    let dest = env.path("bin/nginx/1.28.3");
    let report = extract(ExtractRequest::new(
        &nginx,
        ArchiveFormat::Zip,
        &dest,
        env.stage(),
    ))
    .await
    .unwrap();
    println!("nginx: {report:?}");
    assert_eq!(report.stripped_root.as_deref(), Some("nginx-1.28.3"));
    assert!(dest.join("nginx.exe").is_file());
    assert!(dest.join("conf/nginx.conf").is_file());

    // PHP zips have no top-level folder: nothing is stripped.
    let php = cached(
        "https://downloads.php.net/~windows/releases/php-8.4.27-1-nts-Win32-vs17-x64.zip",
        "php-8.4.27-1-nts-Win32-vs17-x64.zip",
        "dbae154a0a89791f36c3d48e68bae797878333e7d6cb5721e74617de59b63ab7",
    )
    .await;
    let dest = env.path("bin/php/8.4.27-nts-vs17-x64");
    let report = extract(ExtractRequest::new(
        &php,
        ArchiveFormat::Zip,
        &dest,
        env.stage(),
    ))
    .await
    .unwrap();
    println!("php: {report:?}");
    assert_eq!(report.stripped_root, None);
    assert!(dest.join("php.exe").is_file());
    assert!(dest.join("php-cgi.exe").is_file());
    assert!(dest.join("ext").join("php_openssl.dll").is_file());
    env.assert_untouched_staging();
}

#[tokio::test]
#[ignore = "downloads from nodejs.org"]
async fn real_node_archives_online() {
    let env = Env::new();

    // zip with deep node_modules paths (long paths), stripped root.
    let zip = node_archive("node-v24.22.1-win-x64.zip").await;
    let dest = env.path("bin/node/24.22.1");
    let report = extract(ExtractRequest::new(
        &zip,
        ArchiveFormat::Zip,
        &dest,
        env.stage(),
    ))
    .await
    .unwrap();
    println!("node zip: {report:?}");
    assert_eq!(
        report.stripped_root.as_deref(),
        Some("node-v24.22.1-win-x64")
    );
    assert!(dest.join("node.exe").is_file());
    assert!(dest.join("node_modules/npm/package.json").is_file());

    // The same release as 7z.
    let seven = node_archive("node-v24.22.1-win-x64.7z").await;
    let dest7 = env.path("bin/node/24.22.1-7z");
    let report = extract(ExtractRequest::new(
        &seven,
        ArchiveFormat::SevenZ,
        &dest7,
        env.stage(),
    ))
    .await;
    println!("node 7z: {report:?}");
    let report = report.unwrap();
    assert!(dest7.join("node.exe").is_file());
    assert_eq!(
        fs::read(dest7.join("node.exe")).unwrap(),
        fs::read(dest.join("node.exe")).unwrap()
    );
    assert_eq!(
        report.stripped_root.as_deref(),
        Some("node-v24.22.1-win-x64")
    );

    // Headers as tar.gz and tar.xz.
    for (file, format) in [
        ("node-v24.22.1-headers.tar.gz", ArchiveFormat::TarGz),
        ("node-v24.22.1-headers.tar.xz", ArchiveFormat::TarXz),
    ] {
        let archive = node_archive(file).await;
        let dest = env.path(&format!("headers/{file}"));
        let report = extract(ExtractRequest::new(&archive, format, &dest, env.stage()))
            .await
            .unwrap();
        println!("{file}: {report:?}");
        assert_eq!(report.stripped_root.as_deref(), Some("node-v24.22.1"));
        assert!(dest.join("include/node/node.h").is_file());
    }

    // The Linux tarball holds symlinks (bin/npm -> ../lib/...): refused as a whole.
    let linux = node_archive("node-v24.22.1-linux-x64.tar.xz").await;
    let dest = env.path("bin/node-linux/24.22.1");
    let err = extract(ExtractRequest::new(
        &linux,
        ArchiveFormat::TarXz,
        &dest,
        env.stage(),
    ))
    .await
    .unwrap_err();
    println!("linux tar.xz: {err}");
    assert_eq!(err.code(), "verification_failed");
    assert!(err.to_string().contains("symbolic link"), "{err}");
    assert!(!dest.exists());
    env.assert_untouched_staging();
}
